-- Narrow visible ticker explanations to measured concepts; no production execution.
UPDATE lens_tickers SET why='Share of the selected US public-company filings mentioning AI. Disclosure is not measured deployment or an upper bound on adoption; this population is not comparable to enterprise surveys.' WHERE lens_id='growth' AND indicator_id='derived.sec_ai_mention_rate';
UPDATE lens_tickers SET why='Reported AI use in the defined EU enterprise-survey population. Read the observation date, size threshold and industry coverage; this rate cannot be ranked against US filing mentions.' WHERE lens_id='growth' AND indicator_id='dbn.OECD.DSD_ICT_B_DF_BUSINESSES.EU27.A.G14_B.PT_ENT._T.S_GE10';
UPDATE lens_tickers SET why='Reported AI use in the Korean enterprise-survey population at the displayed date. Survey coverage must match before national comparisons; adoption does not determine where productivity gains must appear first.' WHERE lens_id='growth' AND indicator_id='dbn.OECD.ict_business.KOR.ai_adoption';
UPDATE lens_tickers SET why='A copper price series for input-cost context. Many industries use copper, so its price does not verify AI construction spending or identify an AI demand share.' WHERE lens_id='investment' AND indicator_id='fred.PCOPPUSDM';
UPDATE lens_tickers SET why='An aluminium price series for input-cost context, not a measure of quantities used in data centres or an identified AI build-out cost.' WHERE lens_id='investment' AND indicator_id='fred.PALUMUSDM';
UPDATE lens_tickers SET why='A nickel price series for input-cost context. The dashboard does not establish that nickel prices lead computing-capacity announcements.' WHERE lens_id='investment' AND indicator_id='fred.PNICKUSDM';
UPDATE lens_tickers SET why='A lithium price series. Check the displayed endpoint and freshness status; an old observation is not a current quote or evidence that no other source exists.' WHERE lens_id='investment' AND indicator_id='dbn.IMF.PCPS.lithium';
UPDATE lens_tickers SET why='A uranium price series for energy-market context. It does not measure a data centre''s electricity contract, nuclear construction costs or realised AI electricity demand.' WHERE lens_id='investment' AND indicator_id='dbn.IMF.PCPS.uranium';
UPDATE lens_tickers SET why='Average US industrial electricity price per kilowatt-hour. This is not a data-centre-specific tariff or evidence that power is the binding constraint at every proposed site.' WHERE lens_id='investment' AND indicator_id='dbn.EIA.ELEC.PRICE.US-IND.M';
UPDATE lens_tickers SET why='Unemployment in the series-defined US youth population. Age-group unemployment is context, not a direct measure of AI task exposure, foregone hiring or displacement.' WHERE lens_id='labour' AND indicator_id='fred.LNS14024887';
UPDATE lens_tickers SET why='Unemployment in the series-defined Korean youth population. Different national survey and age definitions require checking; this is not a privileged causal test of AI adoption.' WHERE lens_id='labour' AND indicator_id='fred.LRHU24TTKRM156S';
UPDATE lens_tickers SET why='Unemployment among the defined US graduate age group. The rate does not establish the protective effect of a credential or identify automation as the cause of a change.' WHERE lens_id='labour' AND indicator_id='fred.CGBD2534';
UPDATE lens_tickers SET why='US nonfarm-business unit labour costs: labour compensation per unit of real output. Changes combine compensation and productivity; a fall is not uniquely an AI effect or a measure of hourly pay.' WHERE lens_id='labour' AND indicator_id='fred.ULCNFB';
UPDATE lens_tickers SET why='Information-sector employment as a share of the defined US employment total. Industry classification is not a validated ranking of AI exposure, and a share does not remove sector-specific or business-cycle shocks.' WHERE lens_id='labour' AND indicator_id='derived.information_employment_share';
UPDATE lens_tickers SET why='Published semiconductor producer-price index. Its product basket and quality adjustment matter; it is not a current GPU price or the cost of an equivalent AI task.' WHERE lens_id='prices' AND indicator_id='fred.PCU334413334413';
UPDATE lens_tickers SET why='Published data-processing and hosting producer-price index. Its service basket is broader than equivalent AI computation, and contract prices do not alone determine the cost or speed of adoption.' WHERE lens_id='prices' AND indicator_id='fred.PCU518210518210';
UPDATE lens_tickers SET why='Broad commodity-price index for comparison with individual commodity series. It is a weighted source-defined basket, not every raw material or an identified non-AI control group.' WHERE lens_id='prices' AND indicator_id='fred.PALLFNFINDEXM';
UPDATE lens_tickers SET why='Silver price for traded-commodity context. The dashboard does not measure silver quantities used in AI equipment or isolate their contribution to this price.' WHERE lens_id='prices' AND indicator_id='lbma.silver';
UPDATE lens_tickers SET why='Gold price for financial-market context. It responds to several influences and is not a direct or uniquely identified measure of investor anxiety about AI.' WHERE lens_id='prices' AND indicator_id='lbma.gold';
UPDATE lens_tickers SET why='Henry Hub natural-gas spot price. A gas benchmark is not a local electricity tariff, a measured marginal generation mix or the fuel cost of an equivalent AI task.' WHERE lens_id='prices' AND indicator_id='fred.DHHNGSP';
UPDATE lens_tickers SET why='Broad US share-price index in the source''s defined universe. It is not an AI portfolio, a valuation premium attributable to AI or a decomposition of expected earnings and discount rates.' WHERE lens_id='prices' AND indicator_id='fred.SPASTT01USM661N';
